CREATE TABLE education_plans(id TEXT PRIMARY KEY,complex_id INT,title TEXT,track TEXT,level_number INT,segment_count INT DEFAULT 2,created_at TEXT DEFAULT CURRENT_TIMESTAMP,daily_hifz_faces INT DEFAULT 1,daily_rabt_faces INT DEFAULT 1,daily_muraja_faces INT DEFAULT 1,faces_per_half INT DEFAULT 1,faces_per_one INT DEFAULT 1,faces_per_two INT DEFAULT 2);
