CREATE TABLE student_plan_assignments(id TEXT PRIMARY KEY,student_id TEXT,plan_id TEXT,start_segment_index INT,plan_start_date TEXT,start_muraja_segment INT,status TEXT,assigned_by TEXT,assigned_at TEXT DEFAULT CURRENT_TIMESTAMP,transferred_at TEXT,frozen_at TEXT,daily_hifz_faces INT DEFAULT 1,daily_rabt_faces INT DEFAULT 1,daily_muraja_faces INT DEFAULT 1,faces_per_half INT DEFAULT 1,faces_per_one INT DEFAULT 1,faces_per_two INT DEFAULT 2);
